MERGE dbo.JobQueues AS t USING(VALUES(N'sms',N'ارسال پیامک',3,5,60,2,1),(N'reminders',N'یادآوری‌ها',2,5,90,5,2),(N'notifications',N'اعلان‌ها',2,5,60,3,3),(N'system',N'پردازش سیستمی',1,3,120,10,4)) AS s(QueueName,DisplayName,MaxConcurrency,MaxAttempts,VisibilityTimeoutSeconds,PollingIntervalSeconds,SortOrder) ON t.QueueName=s.QueueName WHEN MATCHED THEN UPDATE SET DisplayName=s.DisplayName WHEN NOT MATCHED THEN INSERT(QueueName,DisplayName,MaxConcurrency,MaxAttempts,VisibilityTimeoutSeconds,PollingIntervalSeconds,SortOrder) VALUES(s.QueueName,s.DisplayName,s.MaxConcurrency,s.MaxAttempts,s.VisibilityTimeoutSeconds,s.PollingIntervalSeconds,s.SortOrder);
GO
